const $ = selector => document.querySelector(selector);
const cards = Array.from(document.querySelectorAll('.card'));
const narrow = matchMedia('(max-width:767px)');
const reduce = matchMedia('(prefers-reduced-motion:reduce)');
const config = document.getElementById('portfolio-data');
const portfolio = config ? JSON.parse(config.textContent) : null;
const glyphs = {"0": ["01110", "10001", "10011", "10101", "11001", "10001", "01110"], "1": ["010", "110", "010", "010", "010", "010", "111"], "2": ["01110", "10001", "00001", "00010", "00100", "01000", "11111"], "3": ["11110", "00001", "00001", "01110", "00001", "00001", "11110"], "4": ["00010", "00110", "01010", "10010", "11111", "00010", "00010"], "5": ["11111", "10000", "10000", "11110", "00001", "00001", "11110"], "6": ["01110", "10000", "10000", "11110", "10001", "10001", "01110"], "7": ["11111", "00001", "00010", "00100", "01000", "01000", "01000"], "8": ["01110", "10001", "10001", "01110", "10001", "10001", "01110"], "9": ["01110", "10001", "10001", "01111", "00001", "00001", "01110"], ".": ["0", "0", "0", "0", "0", "0", "1"], "I": ["111", "010", "010", "010", "010", "010", "111"], "a": ["00000", "00000", "01110", "00001", "01111", "10001", "01111"], "e": ["00000", "00000", "01110", "10001", "11111", "10000", "01110"], "g": ["00000", "00000", "01111", "10001", "01111", "00001", "01110"], "i": ["1", "0", "1", "1", "1", "1", "1"], "l": ["10", "10", "10", "10", "10", "10", "01"], "n": ["00000", "00000", "11110", "10001", "10001", "10001", "10001"], "t": ["010", "010", "111", "010", "010", "010", "001"], "r": ["00000", "00000", "10110", "11001", "10000", "10000", "10000"]};
